begin;
set local statement_timeout='30s';
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$begin if value is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end;$$;
do $$
declare org uuid:=gen_random_uuid();actor uuid:=gen_random_uuid();other_actor uuid:=gen_random_uuid();convo uuid:=gen_random_uuid();project_chat uuid:=gen_random_uuid();source uuid:=gen_random_uuid();project_source uuid:=gen_random_uuid();client uuid:=gen_random_uuid();brand uuid:=gen_random_uuid();project uuid:=gen_random_uuid();eng uuid:=gen_random_uuid();cat uuid:=gen_random_uuid();svc uuid:=gen_random_uuid();a public.design_video_references;i integer;
begin
 insert into auth.users(id,email) values(actor,actor||'@example.invalid'),(other_actor,other_actor||'@example.invalid');
 insert into public.organizations(id,name,slug,status) values(org,'Synthetic video rollback','video-qa-'||org,'active');
 insert into public.organization_memberships(organization_id,user_id,role,department_id,status,member_kind) values(org,actor,'operations_admin','design','active','team'),(org,other_actor,'operations_admin','design','active','team');
 insert into public.department_chat_conversations(id,organization_id,department_id,owner_id,title,context_kind) values(convo,org,'design',actor,'Video reference rollback','department_private');
 a:=public.reserve_design_video_reference(org,convo,actor,source,'source.mp4','video/mp4',48,repeat('a',64),'internal',false);
 perform public.reserve_design_video_reference(org,convo,actor,source,'source.mp4','video/mp4',48,repeat('a',64),'internal',false);
 perform pg_temp.ok((select count(*)=1 from public.design_video_references where id=source),'stable reserve replay');
 begin perform public.reserve_design_video_reference(org,convo,actor,source,'changed.mp4','video/mp4',48,repeat('a',64),'internal',false);raise exception 'FAIL changed identity';exception when unique_violation then raise notice 'PASS changed inputs conflict';end;
 begin perform public.reserve_design_video_reference(org,convo,actor,gen_random_uuid(),'source.mp4','video/mp4',48,repeat('a',64),'internal',true);raise exception 'FAIL AI transfer';exception when check_violation then raise notice 'PASS AI consent forbidden';end;
 begin perform public.read_design_video_references(org,convo,other_actor);raise exception 'FAIL foreign actor';exception when insufficient_privilege then raise notice 'PASS other admin cannot read owner original';end;
 begin perform public.read_design_video_references(gen_random_uuid(),convo,actor);raise exception 'FAIL foreign org';exception when insufficient_privilege then raise notice 'PASS foreign org denied';end;
 begin perform public.finalize_design_video_reference(org,convo,actor,source,repeat('b',64),48,'video/mp4','reference_only',null,'reference');raise exception 'FAIL changed hash';exception when check_violation then raise notice 'PASS changed checksum denied';end;
 begin perform public.finalize_design_video_reference(org,convo,actor,source,repeat('a',64),48,'video/mp4',null,null,'reference');raise exception 'FAIL incomplete ready';exception when check_violation then raise notice 'PASS NULL ready metadata denied';end;
 begin perform public.finalize_design_video_reference(org,convo,actor,source,repeat('a',64),48,'video/mp4','reference_only','transcript','reference');raise exception 'FAIL transcript';exception when check_violation then raise notice 'PASS extracted video text forbidden';end;
 perform public.finalize_design_video_reference(org,convo,actor,source,repeat('a',64),48,'video/mp4','reference_only',null,'reference');
 perform public.finalize_design_video_reference(org,convo,actor,source,repeat('a',64),48,'video/mp4','reference_only',null,'reference');
 perform pg_temp.ok((select status='ready' and not ai_use_allowed and extracted_text is null from public.design_video_references where id=source),'ready finalization exact replay reference only');
 begin update public.design_video_references set original_name='changed.mp4' where id=source;raise exception 'FAIL original mutation';exception when insufficient_privilege then raise notice 'PASS original identity immutable';end;
 begin delete from public.design_video_references where id=source;raise exception 'FAIL original deletion';exception when insufficient_privilege then raise notice 'PASS original retained';end;
 begin perform public.append_design_private_message_sources(org,convo,actor,gen_random_uuid(),'Video must not become AI input',array[source]);raise exception 'FAIL video selected as text';exception when insufficient_privilege or invalid_parameter_value then raise notice 'PASS video ID cannot become private AI text source';end;
 perform pg_temp.ok((select count(*)=0 from public.department_chat_messages where conversation_id=convo),'upload and rejected source create no messages');
 perform public.revoke_design_video_reference(org,convo,actor,source);
 begin perform public.finalize_design_video_reference(org,convo,actor,source,repeat('a',64),48,'video/mp4','reference_only',null,'reference');raise exception 'FAIL revoked finalize';exception when insufficient_privilege then raise notice 'PASS revoked cannot finalize';end;
 begin update public.design_video_references set status='ready' where id=source;raise exception 'FAIL revive';exception when insufficient_privilege then raise notice 'PASS revoked cannot revive';end;
 update public.department_chat_conversations set state='archived',archived_at=clock_timestamp() where id=convo;
 begin perform public.read_design_video_references(org,convo,actor);raise exception 'FAIL archived';exception when insufficient_privilege then raise notice 'PASS archived chat denied';end;
 update public.department_chat_conversations set state='active',archived_at=null where id=convo;
 insert into public.clients(id,organization_id,name) values(client,org,'Synthetic video client');
 insert into public.agency_clients(id,organization_id,legacy_client_id,canonical_client_id,name) values(client,org,client,client,'Synthetic agency client');
 insert into public.brands(id,organization_id,client_id,name) values(brand,org,client,'Synthetic brand');
 insert into public.projects(id,organization_id,name,client_id) values(project,org,'Synthetic video project',client);
 insert into public.engagements(id,organization_id,client_id,brand_id,legacy_project_id,project_id,name,created_by,status) values(eng,org,client,brand,project,project,'Synthetic exact Design',actor,'active');
 insert into public.service_catalog(id,organization_id,department_id,slug,name,is_active) values(cat,org,'design','video_reference_qa','Synthetic Design',true);
 insert into public.engagement_services(id,organization_id,engagement_id,service_id,status,owner_id,activated_by) values(svc,org,eng,cat,'active',actor,actor);
 insert into public.department_chat_conversations(id,organization_id,department_id,owner_id,title,context_kind,project_id,engagement_id) values(project_chat,org,'design',actor,'Project private video','department_project',project,eng);
 a:=public.reserve_design_video_reference(org,project_chat,actor,project_source,'project.mov','video/quicktime',48,repeat('a',64),'confidential',false);
 perform pg_temp.ok(a.id=project_source,'exact active project owner can reserve');
 begin perform public.read_design_video_references(org,project_chat,other_actor);raise exception 'FAIL shared admin';exception when insufficient_privilege then raise notice 'PASS teammate cannot read project original';end;
 update public.service_catalog set is_active=false where id=cat;
 begin perform public.read_design_video_references(org,project_chat,actor);raise exception 'FAIL paused service';exception when insufficient_privilege then raise notice 'PASS paused Design service denied';end;
 update public.service_catalog set is_active=true where id=cat;
 update public.projects set archived_at=clock_timestamp() where id=project;
 begin perform public.read_design_video_references(org,project_chat,actor);raise exception 'FAIL archived project';exception when insufficient_privilege then raise notice 'PASS archived project denied';end;
 update public.projects set archived_at=null where id=project;
 update public.organization_memberships set status='revoked' where organization_id=org and user_id=actor;
 begin perform public.read_design_video_references(org,convo,actor);raise exception 'FAIL membership revoked';exception when insufficient_privilege then raise notice 'PASS revoked membership denies original';end;
 perform pg_temp.ok(not has_table_privilege('authenticated','public.design_video_references','select,insert,update,delete'),'direct authenticated rights closed');
 perform pg_temp.ok(not has_table_privilege('anon','public.design_video_references','select,insert,update,delete'),'direct anonymous rights closed');
 perform pg_temp.ok(not has_table_privilege('service_role','public.design_video_references','delete,truncate'),'service cannot delete or truncate originals');
 perform pg_temp.ok(not has_function_privilege('authenticated','public.read_design_video_references(uuid,uuid,uuid)','execute'),'direct actor-spoof RPC closed');
 perform pg_temp.ok((select relrowsecurity from pg_class where oid='public.design_video_references'::regclass),'video reference RLS enabled');
 perform pg_temp.ok((select not public and file_size_limit=20971520 from storage.buckets where id='design-video-references'),'private bounded storage');
end;$$;
rollback;
